//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = 'ULDSTF39204.xml';
scwin.v_schdl_adm_itm_tp_cd = "";
scwin.v_up_schdl_adm_itm_tp_cd = "";
scwin.v_ldMktTpCd = "";
scwin.v_ldMktTpCd_g1 = "";
scwin.v_ldMktTpCd_g2 = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_search = function() {
    var url = "/DisclosureSchedule.do?method=listSchdlTpCd";
    url += "&LD_MKT_TP_CD=1";
    url += "&UP_SCHDL_ADM_ITM_TP_CD=";
    url += "&SCHDL_ADM_ITM_TP_CD=" + scwin.v_schdl_adm_itm_tp_cd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    MxDataSet_schdl_tp_cd_1.DataID = encodeURI(url);
    MxDataSet_schdl_tp_cd_1.reset();
    var url = "/DisclosureSchedule.do?method=listSchdlTpCd";
    url += "&LD_MKT_TP_CD=2";
    url += "&UP_SCHDL_ADM_ITM_TP_CD=";
    url += "&SCHDL_ADM_ITM_TP_CD=" + scwin.v_schdl_adm_itm_tp_cd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    MxDataSet_schdl_tp_cd_2.DataID = encodeURI(url);
    MxDataSet_schdl_tp_cd_2.reset();
    var url = "/DisclosureSchedule.do?method=listSchdlTpCd";
    url += "&LD_MKT_TP_CD=6";
    url += "&UP_SCHDL_ADM_ITM_TP_CD=";
    url += "&SCHDL_ADM_ITM_TP_CD=" + scwin.v_schdl_adm_itm_tp_cd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    MxDataSet_schdl_tp_cd_3.DataID = encodeURI(url);
    MxDataSet_schdl_tp_cd_3.reset();
};
scwin.gform_onload = function() {
    scwin.v_schdl_adm_itm_tp_cd = $c.frame.path("../").scwin.v_schdl_adm_itm_tp_cd;
    scwin.v_ldMktTpCd = $c.frame.path("../").scwin.v_ldMktTpCd;
    scwin.fn_search();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
